content:
  env:
    SOLUTION: ${{ inputs.solution }}
  run: |
    dotnet restore "$SOLUTION"
    dotnet build "$SOLUTION" --no-restore --configuration Release -warnaserror
- name: Install and initialize Dapr
  uses: Hexalith/Hexalith.Builds/Github/dapr-init@c171c7265e70806f09f6ac54130aa6e28ef74395 # BUILD-REL-1
  with:
    version: ${{ inputs.dapr-version }}
    runtime-version: ${{ inputs.dapr-runtime-version }}
- name: Prepare Aspire tier
  if: ${{ inputs.aspire-prepare-script != '' }}
  timeout-minutes: ${{ inputs.aspire-prepare-timeout-minutes }}
  shell: bash
  env:
    ASPIRE_PREPARE_SCRIPT: ${{ inputs.aspire-prepare-script }}
